const { chromium } = require('playwright');
const fs = require('fs');
const KP = fs.readFileSync(__dirname + '/../../kp/package/dist/kaplay.js', 'utf8');
(async () => {
  const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.route('https://cdn.jsdelivr.net/**', r => r.fulfill({ body: KP, contentType: 'application/javascript' }));
  await ctx.route('https://fonts.**', r => r.fulfill({ body: '' }));
  const p = await ctx.newPage();
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => { if (m.type()==='error') errs.push('console: '+m.text()); });
  await p.addInitScript(() => {
    let n = 0;
    const s = async () => ({ text: '' });
    s.json = async (input) => { n++; window.__lastPrompt = input;
      if (n === 1) return { reply: 'Her er forslaget mitt!', question: null, proposal: { title: 'Høyere hopp', changes: ['HOPP fra 640 til 900'], why: 'jump() gir figuren fart oppover.', usedLibrary: ['api.kaplay.body-jump'], code: window.__tpl.replace('const HOPP = 640;', 'const HOPP = 900;') } };
      return { reply: 'Jeg rettet det.', question: null, proposal: { title: 'Ødelagt', changes: ['krasj'], why: '', usedLibrary: [], code: 'kaplay({global:true});\nadd([rect(10,10), pos(0,0)]);\nfinnesIkke();' } };
    };
    window.claude = { use: async (n) => n === 'sample' ? s : null };
  });
  const html = "<!doctype html><html><head><meta charset=utf-8></head><body>" + fs.readFileSync(__dirname + "/spillverksted-prototype.html", "utf8").replace("https://cdn.jsdelivr.net/npm/kaplay@3001.0.19/dist/kaplay.js","http://127.0.0.1:8765/kaplay.js") + "</body></html>";
  fs.writeFileSync(__dirname + '/_t.html', html);
  await p.goto('file://' + __dirname + '/_t.html');
  await p.evaluate(() => { window.__tpl = TEMPLATES['template.platformer']; });
  await p.screenshot({ path: 'p-tom.png' });
  await p.click('button[data-tpl="template.platformer"] >> nth=0');
  await p.waitForTimeout(1800);
  console.log('status1', await p.textContent('#status'));
  await p.fill('#ask', 'Kan figuren hoppe høyere?'); await p.click('#send');
  await p.waitForTimeout(1800);
  console.log('status2', await p.textContent('#status'), '| hl lines', await p.locator('#code span.hl').count());
  await p.screenshot({ path: 'p-fylt.png' });
  await p.click('button[data-act="accept"]'); await p.waitForTimeout(300);
  console.log('versions', await p.locator('.ver').count());
  await p.fill('#ask', 'Lag noe rart'); await p.click('#send');
  await p.waitForTimeout(1800);
  console.log('status3', await p.textContent('#status'), '| err card', await p.locator('.err').count(), await p.locator('#code span.bad').count());
  await p.screenshot({ path: 'p-feil.png' });
  await p.click('button[data-act="discard"]'); await p.waitForTimeout(1500);
  console.log('status4', await p.textContent('#status'));
  await p.click('button[data-restore="0"]'); await p.waitForTimeout(300);
  console.log('versions', await p.locator('.ver').count());
  await p.reload(); await p.waitForTimeout(1500);
  console.log('after reload versions', await p.locator('.ver').count(), 'status', await p.textContent('#status'));
  await p.setViewportSize({ width: 400, height: 860 }); await p.waitForTimeout(300);
  console.log('hscroll', await p.evaluate(() => document.documentElement.scrollWidth > innerWidth));
  await p.screenshot({ path: 'p-mobil.png', fullPage: true });
  console.log('errors', errs);
  await b.close();
})();
